function toast(message,error=false){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.toggle('error',error);$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,error?6500:3600)}
function caught(error){if(error?.name==='AbortError')return;console.error(error);toast(error?.message||'操作未完成，请重试。',true)}
async function ask(title,html,{submit='确定',cancel='取消',width='440px'}={}){layerMove?.cancel();closeMenu();const d=$('#dialog');if(d.open)d.close();$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;$('#dialog-submit').textContent=submit;$('#dialog-cancel').textContent=cancel;$('#dialog-submit').hidden=!submit;$('#dialog-cancel').hidden=!cancel;d.style.width=width;d.returnValue='';d.showModal();return new Promise(resolve=>{let done=false;const finish=value=>{if(done)return;done=true;d.removeEventListener('close',onClose);$('#dialog-form').removeEventListener('submit',onSubmit);d.close();resolve(value)};const onClose=()=>finish(null);const onSubmit=e=>{e.preventDefault();finish(Object.fromEntries(new FormData($('#dialog-form'))))};$('#dialog-form').addEventListener('submit',onSubmit);d.addEventListener('close',onClose);$('#dialog-cancel').onclick=()=>finish(null);$('#dialog-close').onclick=()=>finish(null);setTimeout(()=>$('#dialog-body input:not([type=checkbox]),#dialog-body select')?.focus(),30)})}
