function settings(){return{moveAutoSelect:state.moveAutoSelect,moveKeepInside:state.moveKeepInside,referenceMode:state.referenceMode,baseWidth:state.baseWidth,baseHeight:state.baseHeight,activeDocId:state.activeId,showGuides:state.showGuides,snapToGuides:state.snapToGuides,showGrid:state.showGrid,gridSize:state.gridSize,workspaceName:state.workspaceName,pixelDisplay:state.pixelDisplay,workbench:workbench?.serialize()}}
