function switchDoc(id){if(id===state.activeId)return;workbench?.deactivate();finishPending();state.selection=null;state.activeId=id;state.pointer=null;$('#text-editor-box').hidden=true;renderUI();persist()}
function captureRefs(){return {guides:JSON.parse(JSON.stringify(state.guides)),referenceMode:state.referenceMode,baseWidth:state.baseWidth,baseHeight:state.baseHeight}}
function restoreRefs(entry){if(Array.isArray(entry))state.guides=JSON.parse(JSON.stringify(entry));else Object.assign(state,JSON.parse(JSON.stringify(entry)));updateHistoryButtons()}
function updateHistoryButtons(){$$('[data-action=undo]').forEach(e=>e.disabled=!doc().canUndo&&!state.selection?.float&&!(state.lastAction==='guide'&&state.guideHistoryIndex>0));$$('[data-action=redo]').forEach(e=>e.disabled=!doc().canRedo&&!(state.lastAction==='guide'&&state.guideHistoryIndex<state.guideHistory.length-1))}
function snapshotGuides(){state.guideHistory=state.guideHistory.slice(0,state.guideHistoryIndex+1);state.guideHistory.push(captureRefs());if(state.guideHistory.length>40)state.guideHistory.shift();state.guideHistoryIndex=state.guideHistory.length-1;state.lastAction='guide';state.workspaceDirty=true;updateHistoryButtons();renderGuides();requestRender();persist()}
function addGuide(type,p){const g={id:uid(),type,x:0,y:0,label:(type==='point'?'参考点':type==='h'?'水平线':'垂直线')+' '+String(state.guides.filter(x=>x.type===type).length+1).padStart(2,'0'),color:type==='v'?'#7c9e99':'#de995f',visible:true,locked:false};storePosition(g,p);state.guides.push(g);state.selectedGuide=g.id;snapshotGuides();return g}
async function editGuide(g){const p=guidePosition(g),result=await ask('编辑共享参考',row('名称',`<input name="label" value="${esc(g.label)}" maxlength="60" required>`)+row('X 坐标',`<input name="x" type="number" step="1" value="${Math.round(p.x)}" ${g.type==='h'?'disabled':''}>`)+row('Y 坐标',`<input name="y" type="number" step="1" value="${Math.round(p.y)}" ${g.type==='v'?'disabled':''}>`)+row('颜色',`<input name="color" type="color" value="${esc(g.color)}">`)+`<div class="form-note">${state.referenceMode==='relative'?'按当前画布输入像素位置，其他素材按相对比例同步。':'使用相同像素坐标，立即同步到工作区所有素材。'}</div>`);if(!result)return;g.label=result.label;g.color=result.color;storePosition(g,{x:result.x===undefined?p.x:+result.x,y:result.y===undefined?p.y:+result.y});snapshotGuides()}
function rectSelection(a,b){const d=doc(),ax=clamp(a.x,0,d.width),ay=clamp(a.y,0,d.height),bx=clamp(b.x,0,d.width),by=clamp(b.y,0,d.height),x=Math.min(d.width-1,Math.floor(Math.min(ax,bx))),y=Math.min(d.height-1,Math.floor(Math.min(ay,by))),w=clamp(Math.ceil(Math.max(ax,bx))-x,1,d.width-x),h=clamp(Math.ceil(Math.max(ay,by))-y,1,d.height-y);return{x,y,w,h,layerId:d.activeLayerId}}
function selectedPixels(){const d=doc(),s=state.selection;if(!s)return cloneCanvas(cached());if(s.float)return cloneCanvas(s.float);const c=makeCanvas(s.w,s.h),cctx=c.getContext('2d');cctx.drawImage(d.layers.find(l=>l.id===s.layerId)?.canvas||d.activeLayer.canvas,-s.x,-s.y);if(s.mask){cctx.globalCompositeOperation='destination-in';cctx.drawImage(s.mask,0,0)}if(state.transparentSelection){const pixels=cctx.getImageData(0,0,c.width,c.height),color=state.secondary.match(/\w\w/g)?.map(n=>parseInt(n,16));if(color)for(let i=0;i<pixels.data.length;i+=4)if(pixels.data[i]===color[0]&&pixels.data[i+1]===color[1]&&pixels.data[i+2]===color[2])pixels.data[i+3]=0;cctx.putImageData(pixels,0,0)}return c}
function eraseSelectionPixels(s){const d=doc(),l=d.layers.find(l=>l.id===s.layerId)||d.activeLayer;if(l.locked)throw Error('当前图层已锁定，请先解锁。');const c=l.canvas.getContext('2d');if(s.mask){c.save();c.globalCompositeOperation='destination-out';c.drawImage(s.mask,s.x,s.y);c.restore()}else c.clearRect(s.x,s.y,s.w,s.h);invalidate()}
function liftSelection(){const s=state.selection;if(!s||s.float)return;const l=doc().layers.find(l=>l.id===s.layerId)||doc().activeLayer;if(l.locked)throw Error('当前图层已锁定，请先解锁。');s.sourceBase=cloneCanvas(l.canvas);s.originalX=s.x;s.originalY=s.y;s.float=selectedPixels();eraseSelectionPixels(s)}
