document.addEventListener('paste',async e=>{if(e.target.matches('input,textarea'))return;const images=[...(e.clipboardData?.files||[])].filter(f=>f.type.startsWith('image/'));if(images.length){e.preventDefault();try{const r=await IO.importFiles(images);if(r.docs[0])pasteCanvas(composite(r.docs[0]))}catch(error){caught(error)}}});
let dragDepth=0;document.addEventListener('dragenter',e=>{if(e.dataTransfer?.types.includes('Files')){e.preventDefault();dragDepth++;document.body.classList.add('dragging-files')}});document.addEventListener('dragover',e=>{if(e.dataTransfer?.types.includes('Files')){e.preventDefault();e.dataTransfer.dropEffect='copy'}});document.addEventListener('dragleave',e=>{if(e.dataTransfer?.types.includes('Files')&&--dragDepth<=0)document.body.classList.remove('dragging-files')});document.addEventListener('drop',e=>{e.preventDefault();dragDepth=0;document.body.classList.remove('dragging-files');if(e.dataTransfer.files.length)importImages(e.dataTransfer.files).catch(caught)});
document.addEventListener('keydown',e=>{if($('#dialog').open||regionCapture?.isPreviewOpen())return;const typing=e.target.closest('input,textarea,select,[contenteditable]:not([contenteditable=false])');if(typing)return;const mod=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();if(!['paint','retouch'].includes(state.mode)){if(mod&&key==='s'){e.preventDefault();action('save-project').catch(caught)}if(mod&&key==='o'){e.preventDefault();action('open').catch(caught)}if(state.mode==='padding'&&mod&&(key==='z'||key==='y')){e.preventDefault();action(key==='y'||e.shiftKey?'redo':'undo').catch(caught)}return}if(regionCapture?.handleKey(e))return;try{if(!state.gesture&&layerMove?.handleKey(e))return}catch(error){caught(error);return}if(mod){const actions={n:'new',o:'open',s:e.shiftKey?'save-as':'save',z:e.shiftKey?'redo':'undo',y:'redo',a:'select-all',c:'copy',x:'cut',p:'print','0':'fit','1':'actual',"'":'toggle-grid'};if(key==='v'){if(state.clipboard){e.preventDefault();paste().catch(caught)}return}if(actions[key]){e.preventDefault();action(actions[key]).catch(caught);return}if(key==='+'||key==='='){e.preventDefault();setZoom(getView().z*1.25)}if(key==='-'){e.preventDefault();setZoom(getView().z*.8)}return}if(e.code==='Space'){e.preventDefault();state.space=true;board.style.cursor='grab';return}if(key==='escape'){cancelGesture();if(state.selection?.float)cancelFloating();else state.selection=null;if(state.curve||state.polygon){restoreLayer((state.curve||state.polygon).base);state.curve=null;state.polygon=null;invalidate()}$('#text-editor-box').hidden=true;$('.editor-panel').classList.remove('expanded');closeMenu();renderSelectionStatus();renderTools();requestRender();return}if(key==='enter'){finishPending();state.selection=null;renderSelectionStatus();requestRender();return}if(key==='delete'||key==='backspace'){e.preventDefault();layerMove?.cancel();if(state.selectedGuide){state.guides=state.guides.filter(g=>g.id!==state.selectedGuide);state.selectedGuide=null;snapshotGuides()}else deleteSelection();return}if(key.startsWith('arrow')&&state.selection){e.preventDefault();try{liftSelection();const n=e.shiftKey?10:1;state.selection.x+=key==='arrowleft'?-n:key==='arrowright'?n:0;state.selection.y+=key==='arrowup'?-n:key==='arrowdown'?n:0;requestRender()}catch(error){caught(error)}return}const tools={v:'move',k:'capture',b:'brush',p:'pencil',e:'eraser',f:'fill',i:'eyedropper',t:'text',m:'select',l:'lasso',h:'hand',z:'zoom'};if(tools[key]){setTool(tools[key]);return}if(key==='x')action('swap-colors');if(key==='['||key===']'){state.size=clamp(state.size+(key==='['?-1:1),1,500);renderTools()}});
document.addEventListener('keyup',e=>{if(e.code==='Space'){state.space=false;renderTools()}});window.addEventListener('blur',()=>{state.space=false;renderTools()});window.addEventListener('beforeunload',e=>{if(state.docs.some(d=>d.dirty)||state.selection?.float||state.workspaceDirty){e.preventDefault();e.returnValue=''}});new ResizeObserver(()=>{if(doc()?.view?.fit)fit(false);requestRender()}).observe(viewport);
